try (java.io.InputStream is1 = new java.io.FileInputStream(grid_png);
     java.io.InputStream is2 = new java.io.FileInputStream(grid_jpeg)) {

    java.util.List<java.awt.image.BufferedImage> thumbnails = net.coobird.thumbnailator.Thumbnails.fromInputStreams(java.util.Arrays.asList(is1, is2))
        .size(50, 50)
        .asBufferedImages();

    assert thumbnails.size() == 2 : "Expected 2 thumbnails from 2 input streams";

    java.awt.image.BufferedImage t1 = thumbnails.get(0);
    java.awt.image.BufferedImage t2 = thumbnails.get(1);

    assert t1.getWidth() <= 50 && t1.getHeight() <= 50 : "Thumbnail 1 dimensions exceed 50x50";
    assert t2.getWidth() <= 50 && t2.getHeight() <= 50 : "Thumbnail 2 dimensions exceed 50x50";

    System.out.println("__CHECK__ fromInputStreams " + thumbnails.size() + "," + t1.getWidth() + "x" + t1.getHeight());
} catch (java.io.IOException e) {
    throw new RuntimeException("Failed to read input streams", e);
}

